using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Collections.Generic;using System.Security.Cryptography;using System.Runtime.InteropServices;using Microsoft.Win32.SafeHandles;using System.ComponentModel;using System.Web.Script.Serialization;
namespace PZ3D {
 // These are configuration-owned source copies, never deployments into the game or Workshop.
 sealed class OwnedSupportInstallations {
  internal sealed class OwnedFile {public string Path,Sha256;public long Length;}
  internal sealed class Receipt {public int Version=1;public string ConfigurationRoot,Id,SourceRoot;public OwnedFile[] Files;public string[] Directories;}
  readonly LauncherComponents service;readonly LauncherConfiguration context;readonly Action<int,string> report;
  internal OwnedSupportInstallations(LauncherComponents service,Action<int,string> report=null){this.service=service;context=service.Context;this.report=report;}
  internal static bool Supports(string id){return id=="ZombieBuddy"||id=="Viewpoint";}
  string Container(string id){if(!Supports(id))throw new IOException("此项目没有本配置安装副本。");return Inside(Path.Combine(context.ComponentsDirectory,"installed"),id);}
  static string Inside(string parent,string relative){string root=Path.GetFullPath(parent).TrimEnd('\\','/'),path=Path.GetFullPath(Path.Combine(root,relative));if(!path.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("安装记录的文件位置无效。");LauncherMaintenance.NoReparse(path);return path;}
  internal string Payload(string id){return Inside(Container(id),"mods/"+id);}
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=int.MaxValue};}
  internal Receipt Read(string id){string folder=Container(id),path=Inside(folder,"installation.json");if(!File.Exists(path))return null;var r=Json().Deserialize<Receipt>(File.ReadAllText(path));if(r==null||r.Version!=1||r.Id!=id||!VersionLibrary.Same(r.ConfigurationRoot,context.Root)||r.Files==null||r.Directories==null||string.IsNullOrEmpty(r.SourceRoot)||!Path.IsPathRooted(r.SourceRoot)||r.Files.Any(f=>f==null||f.Path==null||f.Length<0||f.Sha256==null)||r.Files.Select(f=>f.Path).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=r.Files.Length)throw new IOException(id+"：本配置安装记录无效。");foreach(var f in r.Files)Inside(Payload(id),f.Path);foreach(string dir in r.Directories)Inside(Payload(id),dir);return r;}
  internal bool Installed(string id){try{var r=Read(id);return r!=null&&Directory.Exists(Payload(id))&&r.Files.All(f=>{string path=Inside(Payload(id),f.Path);return File.Exists(path)&&new FileInfo(path).Length==f.Length;});}catch(IOException){return false;}}
  internal string OriginalSource(string id){var r=Read(id);return r==null?null:r.SourceRoot;}
  void Progress(string stage,long count,long total,long bytes,long size){if(report!=null)report(total==0?-1:(int)(count*100/total),stage+" · "+count+" / "+total+" 个文件 · "+bytes+" / "+size+" 字节");}
  static string Digest(Stream input,CancellationToken token){using(var sha=SHA256.Create()){byte[] buffer=new byte[65536];int count;while((count=input.Read(buffer,0,buffer.Length))>0){token.ThrowIfCancellationRequested();sha.TransformBlock(buffer,0,count,null,0);}sha.TransformFinalBlock(new byte[0],0,0);return BitConverter.ToString(sha.Hash).Replace("-","").ToLowerInvariant();}}
  string[] Files(string root,CancellationToken token,out string[] directories){var files=new List<string>();var dirs=new List<string>();var queue=new Queue<string>();queue.Enqueue(root);while(queue.Count>0){token.ThrowIfCancellationRequested();string dir=queue.Dequeue();LauncherMaintenance.NoReparse(dir);if(report!=null&&dirs.Count%20==0)report(-1,"正在扫描安装内容 · 已发现 "+files.Count+" 个文件、"+dirs.Count+" 个目录");foreach(string child in Directory.GetDirectories(dir)){token.ThrowIfCancellationRequested();LauncherMaintenance.NoReparse(child);dirs.Add(child.Substring(root.Length+1));queue.Enqueue(child);}foreach(string file in Directory.GetFiles(dir)){token.ThrowIfCancellationRequested();LauncherMaintenance.NoReparse(file);files.Add(file);}}directories=dirs.ToArray();return files.OrderBy(path=>path,StringComparer.OrdinalIgnoreCase).ToArray();}
  void Verify(string id,Receipt r,CancellationToken token,bool allowMissing=false){
   string root=Payload(id);if(!Directory.Exists(root)&&!allowMissing)throw new IOException(id+"：本配置安装副本已缺失。");string[] dirs=new string[0];var files=Directory.Exists(root)?Files(root,token,out dirs):new string[0];var expected=new HashSet<string>(r.Files.Select(f=>Inside(root,f.Path)),StringComparer.OrdinalIgnoreCase);
   if(!allowMissing&&files.Length!=expected.Count||files.Any(f=>!expected.Contains(f))||dirs.Except(r.Directories,StringComparer.OrdinalIgnoreCase).Any())throw new IOException(id+"：安装目录包含不属于此收据的内容或已缺失，未删除或覆盖。");
   string[] allDirs;var allFiles=Files(Container(id),token,out allDirs);var expectedAll=new HashSet<string>(expected,StringComparer.OrdinalIgnoreCase);expectedAll.Add(Inside(Container(id),"installation.json"));var expectedDirs=new HashSet<string>(r.Directories.Select(dir=>"mods\\"+id+"\\"+dir).Concat(new[]{"mods","mods\\"+id}),StringComparer.OrdinalIgnoreCase);
   if(!allowMissing&&allFiles.Length!=expectedAll.Count||allFiles.Any(file=>!expectedAll.Contains(file))||allDirs.Any(dir=>!expectedDirs.Contains(dir)))throw new IOException(id+"：安装目录包含收据之外的文件或目录，未删除或覆盖。");
   var records=r.Files.Where(f=>!allowMissing||File.Exists(Inside(root,f.Path))).ToArray();long done=0,bytes=0,total=records.Sum(f=>f.Length);foreach(var f in records){token.ThrowIfCancellationRequested();string file=Inside(root,f.Path);using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read))if(input.Length!=f.Length||Digest(input,token)!=f.Sha256)throw new IOException(id+"：已安装文件发生变化，未删除或覆盖："+f.Path);Progress("正在核对 "+id,++done,records.Length,bytes+=f.Length,total);}
   if(!allowMissing&&id=="ZombieBuddy"){var row=service.Inspect(root,id,token);LiveModDiscovery.BuddyBytes(row.Jar??Path.Combine(root,"libs","ZombieBuddy.jar"));}
  }
  T Locked<T>(Func<T> work){if(context.Mode!="launcher")throw new IOException("此操作仅适用于启动器配置的本地安装副本。");string key=LauncherComponents.Hash(Encoding.UTF8.GetBytes(context.Root.ToUpperInvariant()));var held=new List<Mutex>();try{foreach(string prefix in new[]{"OrangeSupport-","OrangeComponents-","OrangeOrdinary-"}){var mutex=new Mutex(false,"Local\\"+prefix+key);bool acquired=false;try{try{acquired=mutex.WaitOne(0);}catch(AbandonedMutexException){acquired=true;}if(!acquired)throw new IOException("此配置的安装内容或模组选择正在修改，请稍后重试。");held.Add(mutex);}catch{mutex.Dispose();throw;}}return work();}finally{foreach(var mutex in held.AsEnumerable().Reverse()){mutex.ReleaseMutex();mutex.Dispose();}}}
  internal string Enable(string id,string source,CancellationToken token,bool update=false){return Locked(()=>{
   token.ThrowIfCancellationRequested();var old=Read(id);if(old!=null&&!update){Verify(id,old,token);token.ThrowIfCancellationRequested();service.Select(Payload(id),id,true,token);return Payload(id);}if(old!=null){Verify(id,old,token,true);if(VersionLibrary.Same(source,Payload(id)))source=old.SourceRoot;}
   var before=service.Inspect(source,id,token);source=before.SourceRoot;if(id=="ZombieBuddy")LiveModDiscovery.BuddyBytes(before.Jar??Path.Combine(source,"libs","ZombieBuddy.jar"));string parent=Path.GetDirectoryName(Container(id));LauncherMaintenance.NoReparse(parent);Directory.CreateDirectory(parent);string stage=Inside(parent,".s"+Guid.NewGuid().ToString("N").Substring(0,8)),target=Container(id),retired=null;bool published=false;Directory.CreateDirectory(stage);try{
    string output=Inside(stage,"mods/"+id);Directory.CreateDirectory(output);string[] dirs;string[] files=Files(source,token,out dirs);foreach(string dir in dirs)Directory.CreateDirectory(Inside(output,dir));long total=files.Sum(file=>new FileInfo(file).Length),done=0,bytes=0;var records=new List<OwnedFile>();Progress("正在复制 "+id,0,files.Length,0,total);
    foreach(string file in files){token.ThrowIfCancellationRequested();string relative=file.Substring(source.Length+1),copy=Inside(output,relative);Directory.CreateDirectory(Path.GetDirectoryName(copy));using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read))using(var destination=new FileStream(copy,FileMode.CreateNew,FileAccess.Write,FileShare.None)){byte[] buffer=new byte[65536];int count;while((count=input.Read(buffer,0,buffer.Length))>0){token.ThrowIfCancellationRequested();destination.Write(buffer,0,count);bytes+=count;Progress("正在复制 "+id,done,files.Length,bytes,total);}destination.Flush(true);input.Position=0;records.Add(new OwnedFile{Path=relative,Length=input.Length,Sha256=Digest(input,token)});}if(LauncherComponents.HashFile(copy)!=records.Last().Sha256)throw new IOException(id+"：复制文件核对失败。");Progress("正在复制 "+id,++done,files.Length,bytes,total);}
    var copied=service.Inspect(output,id,token);if(before.SourceEvidence!=service.Inspect(source,id,token).SourceEvidence||before.Id!=copied.Id)throw new IOException(id+"：来源发生变化。");if(id=="ZombieBuddy")LiveModDiscovery.BuddyBytes(copied.Jar??Path.Combine(output,"libs","ZombieBuddy.jar"));var receipt=new Receipt{ConfigurationRoot=context.Root,Id=id,SourceRoot=source,Files=records.ToArray(),Directories=dirs};LauncherComponents.Atomic(Inside(stage,"installation.json"),Encoding.UTF8.GetBytes(Json().Serialize(receipt)));token.ThrowIfCancellationRequested();
    if(Directory.Exists(target)){if(old==null)throw new IOException(id+"：目标已有非本配置安装内容。");retired=Inside(parent,".r"+Guid.NewGuid().ToString("N").Substring(0,8));Directory.Move(target,retired);}Directory.Move(stage,target);published=true;
    try{service.Select(Payload(id),id,true,CancellationToken.None);}catch{RemoveTree(target);published=false;if(retired!=null){Directory.Move(retired,target);retired=null;}throw;}if(retired!=null){RemoveReplaced(retired,old);retired=null;}return Payload(id);
   }finally{if(Directory.Exists(stage))RemoveTree(stage);if(!published&&retired!=null&&!Directory.Exists(target))Directory.Move(retired,target);}
  });}
  internal void Disable(string id,CancellationToken token){Locked(()=>{token.ThrowIfCancellationRequested();service.SetEnabled(id,false,token);return true;});}
  sealed class DeleteFileHandle:IDisposable {
   [DllImport("kernel32.dll",EntryPoint="CreateFileW",CharSet=CharSet.Unicode,SetLastError=true)]static extern SafeFileHandle Open(string path,uint access,uint share,IntPtr security,uint creation,uint flags,IntPtr template);
   [StructLayout(LayoutKind.Sequential)]struct Disposition {[MarshalAs(UnmanagedType.U1)]public bool Delete;}
   [DllImport("kernel32.dll",SetLastError=true)]static extern bool SetFileInformationByHandle(SafeFileHandle handle,int kind,ref Disposition value,uint size);
   readonly FileStream stream;internal Stream Stream{get{return stream;}}
   internal DeleteFileHandle(string path){LauncherMaintenance.NoReparse(path);var handle=Open(SnapshotFileSystem.NativePath(path),0x80010000,1,IntPtr.Zero,3,0x80,IntPtr.Zero);if(handle.IsInvalid){int error=Marshal.GetLastWin32Error();handle.Dispose();throw new IOException("安装文件仍被占用或无法删除："+path,new Win32Exception(error));}stream=new FileStream(handle,FileAccess.Read);}
   internal void Delete(){var info=new Disposition{Delete=true};if(!SetFileInformationByHandle(stream.SafeFileHandle,4,ref info,1))throw new IOException("无法删除此配置的安装文件。",new Win32Exception(Marshal.GetLastWin32Error()));}
   public void Dispose(){stream.Dispose();}
  }
  internal string[] Uninstall(string id,CancellationToken token){return Locked(()=>{token.ThrowIfCancellationRequested();var r=Read(id);if(r!=null)Verify(id,r,token,true);string target=Container(id);var handles=new List<DeleteFileHandle>();var runtimeHandles=new List<DeleteFileHandle>();var warnings=new List<string>();try{if(r!=null){foreach(var f in r.Files.Where(file=>File.Exists(Inside(Payload(id),file.Path)))){token.ThrowIfCancellationRequested();var handle=new DeleteFileHandle(Inside(Payload(id),f.Path));handles.Add(handle);if(handle.Stream.Length!=f.Length||Digest(handle.Stream,token)!=f.Sha256)throw new IOException(id+"：安装文件正在变化，未删除。");}handles.Add(new DeleteFileHandle(Inside(target,"installation.json")));}if(id=="ZombieBuddy")foreach(string path in LegacyRuntimeBuddyFiles(token,warnings)){DeleteFileHandle handle=null;try{handle=new DeleteFileHandle(path);if(Digest(handle.Stream,token)!=LiveModDiscovery.BuddyHash){warnings.Add("旧运行文件已变化，已保留："+path);continue;}runtimeHandles.Add(handle);handle=null;}catch(OperationCanceledException){throw;}catch(IOException error){warnings.Add("旧运行文件未能移除，已保留："+path+" · "+error.Message);}finally{if(handle!=null)handle.Dispose();}}token.ThrowIfCancellationRequested();service.UnregisterSupport(id,CancellationToken.None);foreach(var handle in handles)handle.Delete();foreach(var handle in runtimeHandles)try{handle.Delete();}catch(IOException error){warnings.Add("旧运行文件未能移除，已保留："+error.Message);}}finally{foreach(var handle in handles.Concat(runtimeHandles))handle.Dispose();}if(r!=null)RemoveEmptyReceiptDirectories(target,r);return warnings.ToArray();});}
  IEnumerable<string> LegacyRuntimeBuddyFiles(CancellationToken token,List<string> warnings){
   string[] folders=new string[0];try{LauncherMaintenance.NoReparse(context.RuntimeDirectory);if(Directory.Exists(context.RuntimeDirectory))folders=Directory.GetDirectories(context.RuntimeDirectory);}catch(Exception error){warnings.Add("旧运行目录无法核对，已保留其中的文件："+error.Message);}
   int inspected=0;foreach(string folder in folders.Where(path=>System.Text.RegularExpressions.Regex.IsMatch(Path.GetFileName(path),"^live-[a-f0-9]{12}$"))){
    token.ThrowIfCancellationRequested();if(report!=null)report(-1,"正在核对旧运行文件 · 已处理 "+(++inspected)+" 个会话");string path=Path.Combine(folder,"ZombieBuddy.jar");bool owned=false;
    try{path=Inside(folder,"ZombieBuddy.jar");if(!File.Exists(path))continue;string manifest=Inside(folder,"live.manifest");var fields=new Dictionary<string,string[]>(StringComparer.Ordinal);
     using(var reader=new StreamReader(manifest,new UTF8Encoding(false,true))){if(reader.ReadLine()!="OZLLIVE1")throw new IOException("运行记录格式不明。");string line;while((line=reader.ReadLine())!=null){token.ThrowIfCancellationRequested();var parts=line.Split('\t');if(!new[]{"game","user","context","choices","buddy"}.Contains(parts[0]))continue;if(fields.ContainsKey(parts[0]))throw new IOException("运行记录存在重复身份。");fields.Add(parts[0],parts.Skip(1).Select(value=>Encoding.UTF8.GetString(Convert.FromBase64String(value))).ToArray());}}
     string[] game,user,root,choices,buddy;owned=fields.TryGetValue("game",out game)&&game.Length==1&&VersionLibrary.Same(game[0],context.Game)&&fields.TryGetValue("user",out user)&&user.Length==1&&VersionLibrary.Same(user[0],context.User)&&fields.TryGetValue("context",out root)&&root.Length==1&&VersionLibrary.Same(root[0],context.Root)&&fields.TryGetValue("choices",out choices)&&choices.Length==1&&VersionLibrary.Same(choices[0],folder)&&fields.TryGetValue("buddy",out buddy)&&buddy.Length==2&&VersionLibrary.Same(buddy[0],path)&&buddy[1]==LiveModDiscovery.BuddyHash;
     if(!owned)warnings.Add("旧运行文件无法确认属于此配置，已保留："+path);
    }catch(OperationCanceledException){throw;}catch(Exception error){warnings.Add("旧运行记录无法核对，已保留文件："+path+" · "+error.Message);}if(owned)yield return path;
   }
  }
  void RemoveEmptyReceiptDirectories(string container,Receipt receipt){string payload=Inside(container,"mods/"+receipt.Id);foreach(string dir in receipt.Directories.Select(relative=>Inside(payload,relative)).Concat(new[]{payload,Inside(container,"mods"),container}).OrderByDescending(path=>path.Length)){LauncherMaintenance.NoReparse(dir);if(Directory.Exists(dir)&&!Directory.EnumerateFileSystemEntries(dir).Any())Directory.Delete(dir,false);}}
  void RemoveReplaced(string container,Receipt receipt){string payload=Inside(container,"mods/"+receipt.Id);foreach(var f in receipt.Files){string path=Inside(payload,f.Path);if(File.Exists(path)){using(var handle=new DeleteFileHandle(path)){if(handle.Stream.Length!=f.Length||Digest(handle.Stream,CancellationToken.None)!=f.Sha256)throw new IOException(receipt.Id+"：旧安装副本发生变化，已保留该文件。");handle.Delete();}}}string record=Inside(container,"installation.json");if(File.Exists(record))using(var handle=new DeleteFileHandle(record))handle.Delete();RemoveEmptyReceiptDirectories(container,receipt);}
  void RemoveTree(string path){string parent=Path.GetFullPath(Path.Combine(context.ComponentsDirectory,"installed")).TrimEnd('\\','/'),full=Path.GetFullPath(path).TrimEnd('\\','/');if(!VersionLibrary.Same(Path.GetDirectoryName(full),parent)||!full.StartsWith(parent+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("安装清理目录不属于此配置。");string[] dirs;Files(full,CancellationToken.None,out dirs);Directory.Delete(full,true);}
 }
}
